import { MobileKey } from "@/types/mobile";
import React, { useEffect, useMemo, useState, createElement, useImperativeHandle } from "react";
import globals, { dynamicCreateModule } from "@/environments/hoc";
import { Avatar, ConfigProvider, Image } from "@arco-design/web-react";
import locales from "@code/locales";
import { languageType } from "@/types/language";
import i18next from "i18next";
import { App } from "@code/App";
import codeApp from "@code/store/app";
import ReactDOM from "react-dom";
import dev from "./store/dev";
import utils from "utils";
import theme from "@/store/theme";
import appUserStore from "@/store/userStore";
import { IfrmaeAppProps, IfrmaeWindowProps } from "@/types/iframe"
import { mainRoutes } from "@code/routes";
import { useObserver } from "mobx-react-lite";
import { flattenTree } from "./utils/tree";
import { addCSS, loadScript, removeCss } from "./utils";
import plugins from "@/store/plugins";
import app from "@/store/app";
import language from "@/store/language";
import design from "@/store/design";

const win: IfrmaeAppProps = window as any;

export const initIframeApp = async () => {
    const { moduleStore, fileStore, userStore, pageStore, pluginsStore } = win;
    app.setStore(win.app.getStore());
    // 全局用户 Store 参数写入
    appUserStore.setStore(userStore.getStore());
    // 插件写入
    plugins.setStore(pluginsStore.getStore());
    // 写入多语言
    language.setStore(win.language.getStore());

    /**
     * 渲染中如果有其他组件，从主页面获取模块组件信息
     */
    globals.m = (uid) => {
        if(globals.state.mModules[uid]) return globals.state.mModules[uid];
        // if(moduleStore){
        //     console.log('moduleStore.elements', uid, moduleStore.elements.has(uid))
        // }
        if(moduleStore && moduleStore.elements.has(uid)){
            const element = moduleStore.elements.get(uid);
            if(element.jsxRender){
                globals.state.mModules[uid] = dynamicCreateModule(element.jsxRender)
                if(element.extraInfo.cssStr){
                    addCSS(element.extraInfo.cssStr, uid)
                }else {
                    removeCss(uid)
                }
                // 改为实时预览
                // return dynamicCreateModule(element.jsxRender);
            }
        }
        return globals.state.mModules[uid] || (() => <span>Null：{uid}</span>);
    }
    
    
    /**
     * 更换其他文件
     */
    globals.h = ((...args: [any, any]) => {
        let [name, props, ...children] = args;
        switch(name){
            case 'img':
            case 'image':
                if(fileStore.imgMap[props.src]){
                    props = { ...props, src: fileStore.imgMap[props.src], alt: props.src }
                }
            break;
            case Image:
                if(fileStore.imgMap[props.src]){
                    props = { ...props, src: fileStore.imgMap[props.src], alt: props.src }
                }
            break;
            case Image.Preview:
                if(fileStore.imgMap[props.src]){
                    props = { ...props, src: fileStore.imgMap[props.src], alt: props.src }
                }
            break;
            case Image.PreviewGroup:
                if(props.srcList && Array.isArray(props.srcList) && props.srcList.length){
                    props = {
                        ...props,
                        srcList: props.srcList.map((url) => {
                            if(fileStore.imgMap[url]) return fileStore.imgMap[url];
                            return url;
                        })
                    }
                }
            break;
        }
        return React.createElement(name, props, ...children)
    }) as any

    Object.assign(window.parent, {
        dev: dev,
        utils,
        theme,
        design: design,
        iframeDesign: null
    } as IfrmaeWindowProps)

    
    for (const o of pageStore.menus) {
        if(o.pageId && pageStore.pages[o.pageId]){
            const page = pageStore.pages[o.pageId];
            if(page.cssStr){
                addCSS(page.cssStr, page.uid)
            }
            // @ts-ignore
            o.component = dynamicCreateModule(await page.getRenderText());
        }
    }
    
    // 写入页面路由
    dev.setRoutes(pageStore.menus);
    // 加载项目和插件信息
    await dev.initAppProject();
    
    // 写入路由
    await dev.initEnv();

    
    codeApp.tenantId = app.appId;

    // 重新加载多语言
    locales.changeLang(locales.lang);

    const flattenList = flattenTree(mainRoutes);
    
    window.parent.postMessage({
        key: MobileKey.IframeAppReady,
    })

    const IframeApp = () => {

        return useObserver(() => {

            useMemo(() => {
                if(pageStore.current){
                    const page = pageStore.pages[pageStore.current]!;
                    if(page.isPage){
                        for (const item of flattenList) {
                            if(item.pageId == pageStore.current){
                                item.component = dynamicCreateModule(page.jsxRender);
                            }
                        }
                        if(page.cssStr){
                            addCSS(page.cssStr, page.uid)
                        }else {
                            removeCss(page.uid)
                        }
                    }else {
                        delete globals.state.mModules[pageStore.current]
                    }
                }
            },[dev.key])

            return <App key={dev.key}/>
        })
    }

    ReactDOM.render(<IframeApp />, document.getElementById('root'));
}